sp_widget.client_script:
api.controller=function($scope) {
  /* widget controller */
  var c = this;
	// Estado inicial (pode ser null, true ou false)
$scope.isLowercase = null;

// Escuta evento do rootScope para atualizar o estado
$scope.$root.$on('toggleCaseEvent', function(event, isLowercase) {
  $scope.isLowercase = isLowercase;
});

};

sp_widget.css:
/* Tipografia base */
body, h5, ol, li, a {
  font-family: 'Roboto Flex', sans-serif !important;
  color: #333;
}

/* Container do widget */
.acessos-widget {
  color: #333;
  margin-bottom: 30px;
}

/* Títulos desktop (linha com ícones nas extremidades) */
.topo-linha {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px; /* espaço entre os elementos */
}

.titulo-esquerda,
.titulo-direita {
  font-size: 16px;
  font-weight: 600;
  white-space: nowrap;
  margin: 0;
}

.titulo-esquerda {
  margin-left: 7rem; /* ajusta para mover um pouco pra direita */
}

.titulo-direita {
  margin-right: 5rem; /* um pouco mais pra direita */
}

.linha-flex {
  flex-grow: 1; 
  height: 1px;
  background-color: #000; 
  margin: 0 10px; 
  border-radius: 1px; 
}

/* Títulos visíveis só no mobile */
.titulo-mobile {
  display: none;
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 10px;
}

.fa.fa-fire{
	color: tomato;
}

.fa.fa-star{
	color: #ffd700;
}

/* Listagem dos mais acessados */
.list-mais-acessados {
  padding-left: 20px;
  margin-top: 10px;
}

.list-mais-acessados li {
  margin-bottom: 15px;
}

.list-mais-acessados {
  list-style-type: decimal; /* mantém a numeração */
  counter-reset: item; /* zera o contador */
  padding-left: 0; /* opcional, ajustar o espaço */
}

.list-mais-acessados li {
  list-style-type: none; /* remove o estilo padrão */
  counter-increment: item; /* incrementa o contador */
  position: relative;
  padding-left: 20px; /* espaço para o número personalizado */
  transform: translateY(10px);
}

.list-mais-acessados li::before {
  content: counter(item); /* exibe só o número */
  position: absolute;
  left: 0;
  top: 0;
  color: #bbb; /* cinza claro */
  font-weight: bold;
}

.list-mais-acessados a {
  text-decoration: none;
}

.list-mais-acessados a:hover {
  text-decoration: underline;
}

/* Últimos acessos */
.ultimos-acessos {
  margin-bottom: 15px;
  transform: translateY(10px);
  margin-right: 10px;
}

.ultimos-acessos a {
  font-weight: 500;
  text-decoration: none;
}

.ultimos-acessos a:hover {
  text-decoration: underline;
}

.categoria {
  font-size: 12px;
  color: #888;
}

.bloco-ultimos {
  margin-left: auto;
}

/* Layout responsivo */
.acessos-wrapper {
  display: flex;
  flex-wrap: wrap;
  border-bottom: 1px solid black;
}

.lowercase-text {
  text-transform: lowercase;
}

.uppercase-text {
  text-transform: uppercase;
}


/* Em telas menores: empilha blocos e mostra títulos internos */
@media (max-width: 800px) {
  .acessos-wrapper {
    flex-direction: column;
  }

  .bloco {
    width: 100%;
    margin-bottom: 20px;
  }

  .bloco-mais {
    order: 1;
  }

  .bloco-ultimos {
    order: 2;
  }

  .topo-linha {
    display: none; /* esconde os títulos com linha no mobile */
  }

  .titulo-mobile {
    display: block; /* mostra os títulos internos no mobile */
  }

  .bloco.bloco-ultimos{
  	margin-left: 2rem;
  }
}

